"""Spike 001b: verify @generated marker × from __future__ import annotations compatibility (D-RIGOR-01 item 8).

Per Recipe 5 (12-RESEARCH.md):

- Copy 001a output `client_generated.py` to a sibling work file `client_with_marker.py`
  (NEVER mutate the 001a baseline; Anti-Pitfall #3 from iteration-1 plan-checker review).
- Prepend the canonical @generated marker via `str.__add__` (NOT `str.replace`)
  to ensure deterministic line ordering (Pitfall 6 mitigation).
- Run the 4 verification commands (`ruff check`, `ruff format --check`,
  `mypy --strict`, `ast.parse`) and capture stdout/stderr/exit codes.
- Also run the same 4 commands against a baseline (unmarked) copy of 001a output to
  isolate marker-introduced failures from pre-existing 001a output noise.
  (001a is FAIL on strict byte-identical; some pre-existing ruff/mypy noise is
  expected and documented in 001a/FINDING.md.)
- Aggregate marker-compatibility verdict PASS iff per-command exit codes are
  IDENTICAL between baseline and marked (i.e., the marker introduces zero NEW
  failures). The absolute exit codes may be non-zero due to inherent 001a noise.

Run from repo root:

    uv run --with unasync python .planning/spikes/SPIKE-005-codegen-tool-choice/001b-ambito-marker-future-compat/experiment.py
"""

from __future__ import annotations

import subprocess
import sys
from pathlib import Path

# --- paths ----------------------------------------------------------------

REPO_ROOT = Path(__file__).resolve().parents[4]
SPIKE_DIR = Path(__file__).resolve().parent
GENERATED_ORIG = (
    REPO_ROOT
    / ".planning/spikes/SPIKE-005-codegen-tool-choice/001a-ambito-round-trip/output/client_generated.py"
)
WORK = SPIKE_DIR / "client_with_marker.py"
BASELINE = SPIKE_DIR / "client_baseline_no_marker.py"
TRANSCRIPTS = SPIKE_DIR / "verification_transcripts.txt"

# --- step 1: copy 001a output to local work file --------------------------

if not GENERATED_ORIG.exists():
    sys.stderr.write(
        f"FATAL: 001a output missing: {GENERATED_ORIG}\nRun 001a experiment first.\n"
    )
    raise SystemExit(2)

ORIG_TEXT = GENERATED_ORIG.read_text()
BASELINE.write_text(ORIG_TEXT)  # unmarked baseline copy

# --- step 2: prepend canonical marker via str.__add__ ---------------------
# Anti-Pitfall 6 (Recipe 5): str.__add__ concat at file start, NOT str.replace.
# Line ordering after prepend:
#   1: marker line 1
#   2: marker line 2
#   3: blank
#   4+: original content (docstring → blank → from __future__ import annotations → rest)

MARKER = (
    "# @generated by unasync from aio.py — DO NOT EDIT BY HAND.\n"
    "# To modify, edit aio.py and run `make codegen` (Phase 16 setup).\n"
    "\n"
)
WORK.write_text(MARKER + ORIG_TEXT)

# --- step 3: run 4 verification commands twice (baseline + marked) -------


def cmd_set(target: Path) -> list[tuple[str, list[str]]]:
    return [
        ("ruff check", ["uv", "run", "ruff", "check", str(target)]),
        ("ruff format --check", ["uv", "run", "ruff", "format", "--check", str(target)]),
        ("mypy --strict", ["uv", "run", "mypy", "--strict", str(target)]),
        (
            "ast.parse",
            [
                "uv",
                "run",
                "python",
                "-c",
                f"import ast; ast.parse(open({str(target)!r}).read())",
            ],
        ),
    ]


def run_cmds(label_prefix: str, target: Path) -> list[tuple[str, int, str, str]]:
    out: list[tuple[str, int, str, str]] = []
    for label, argv in cmd_set(target):
        proc = subprocess.run(argv, capture_output=True, text=True, cwd=REPO_ROOT)
        out.append((f"{label_prefix} {label}", proc.returncode, proc.stdout, proc.stderr))
    return out


baseline_results = run_cmds("baseline", BASELINE)
marked_results = run_cmds("marked", WORK)

# --- step 4: write verification_transcripts.txt --------------------------

with TRANSCRIPTS.open("w") as fh:
    fh.write(
        "# Spike 001b — verification transcripts\n"
        "# Each command runs twice: against the unmarked 001a baseline and against the\n"
        "# 001a baseline with the @generated marker prepended. Marker compatibility =\n"
        "# per-command exit codes IDENTICAL between baseline and marked (i.e., marker\n"
        "# introduces zero new failures). Absolute non-zero exit codes inherited from\n"
        "# 001a are documented as Recipe-2 inherent-asymmetry in 001a/FINDING.md.\n\n"
    )
    # Required-by-acceptance-criteria stanzas (the 4 labeled "marked" sections that the
    # acceptance-criteria grep looks for must use the exact labels). We emit BOTH sets.
    for label, rc, stdout, stderr in marked_results:
        # Strip "marked " prefix for the acceptance-criteria-required label.
        bare = label.removeprefix("marked ")
        fh.write(f"=== {bare} ===\n")
        fh.write(f"exit {rc}\n")
        if stdout:
            fh.write(stdout)
            if not stdout.endswith("\n"):
                fh.write("\n")
        if stderr:
            fh.write(stderr)
            if not stderr.endswith("\n"):
                fh.write("\n")
        fh.write("\n")
    fh.write("# --- Baseline (no marker) results, for delta comparison -----------\n\n")
    for label, rc, stdout, stderr in baseline_results:
        bare = label.removeprefix("baseline ")
        fh.write(f"=== baseline {bare} ===\n")
        fh.write(f"exit {rc}\n")
        if stdout:
            fh.write(stdout)
            if not stdout.endswith("\n"):
                fh.write("\n")
        if stderr:
            fh.write(stderr)
            if not stderr.endswith("\n"):
                fh.write("\n")
        fh.write("\n")

# --- step 5: aggregate verdict -------------------------------------------
# Marker compatibility = per-command exit codes IDENTICAL between baseline and marked.
# Absolute exit codes may be non-zero due to 001a inherent-asymmetry noise (documented
# in 001a/FINDING.md as 10 hunks, all class 1/2/4 per Recipe 2 — zero NO-GO triggers).

delta_pass = True
delta_breakdown: list[str] = []
for (b_label, b_rc, _, _), (m_label, m_rc, _, _) in zip(
    baseline_results, marked_results, strict=True
):
    bare = b_label.removeprefix("baseline ").replace(" ", "_")
    same = b_rc == m_rc
    delta_pass = delta_pass and same
    delta_breakdown.append(
        f"{bare}=baseline_rc:{b_rc}/marked_rc:{m_rc}/{'MARKER-NEUTRAL' if same else 'MARKER-INTRODUCED'}"
    )

print(f"Transcripts written to {TRANSCRIPTS}")
print(f"SPIKE 001b VERDICT: {'PASS' if delta_pass else 'FAIL'} marker-compatibility:")
for line in delta_breakdown:
    print(f"  {line}")

raise SystemExit(0 if delta_pass else 1)
